    };
    let parsed = match parse_calendar(body_str, IcsParserLimits::default()) {
        Ok(parsed) => parsed,
        Err(_) => return dav_bad_request("invalid calendar data"),
    };
    if parsed.events.is_empty() {
        return dav_bad_request("at least one VEVENT is required");
    }
    if let Err(message) = validate_dav_write(&parsed) {
        return dav_bad_request(message);
    }
    let masters: Vec<_> = parsed
        .events
        .iter()
        .filter(|event| event.recurrence_id.is_none())
        .collect();
    if masters.len() != 1 {
        return dav_bad_request("a recurring resource requires exactly one master VEVENT");
    }
    let master = masters[0];
    let exceptions: Vec<_> = parsed
